    while (q.length > 0) {
        const u = q.shift();
        for (const [v, w] of adj[u]) {
            dp[v] = Math.max(dp[v], dp[u] + w);
            if (--inDegree[v] === 0) q.push(v);
        }
    }
    return Math.max(...dp);
};

