    vector<vector<int>> allPathsSourceTarget(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> res;
        vector<int> path = {0};
        auto dfs = [&](auto& self, int u) -> void {
            if (u == n - 1) {
                res.push_back(path);
                return;
            }
            for (int v : graph[u]) {
                path.push_back(v);
                self(self, v);
                path.pop_back();
            }
        };
