            while (sz-- > 0) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0) {
