        int[] st = new int[asteroids.length];
        int top = 0;
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && top > 0 && st[top - 1] > 0) {
                if (st[top - 1] < -a) {
                    top--;
                } else if (st[top - 1] == -a) {
                    top--;
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) st[top++] = a;
        }
        int[] res = new int[top];
        System.arraycopy(st, 0, res, 0, top);
        return res;
    }
