class Solution {
    static class Poly {
        Map<List<String>, Integer> terms = new HashMap<>();
        Poly() {}
        Poly(int c) { if (c != 0) terms.put(Collections.emptyList(), c); }
        Poly(String v) { terms.put(Collections.singletonList(v), 1); }

