class Solution {
    private boolean isLeaf(TreeNode node) {
        return node != null && node.left == null && node.right == null;
    }
    private void addLeaves(TreeNode node, List<Integer> res) {
        if (node == null) return;
        if (isLeaf(node)) {
            res.add(node.val);
            return;
        }
        addLeaves(node.left, res);
        addLeaves(node.right, res);
    }
    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        if (root == null) return new ArrayList<>();
        List<Integer> res = new ArrayList<>();
        if (!isLeaf(root)) res.add(root.val);

        TreeNode curr = root.left;
        while (curr != null) {
            if (!isLeaf(curr)) res.add(curr.val);
            curr = curr.left != null ? curr.left : curr.right;
        }

        addLeaves(root, res);

        List<Integer> rightBoundary = new ArrayList<>();
        curr = root.right;
        while (curr != null) {
            if (!isLeaf(curr)) rightBoundary.add(curr.val);
            curr = curr.right != null ? curr.right : curr.left;
        }
        Collections.reverse(rightBoundary);
        res.addAll(rightBoundary);
        return res;
    }
}

var boundaryOfBinaryTree = function(root) {
    if (!root) return [];
    function isLeaf(node) {
        return node && !node.left && !node.right;
    }

    const res = [];
    if (!isLeaf(root)) res.push(root.val);

    let curr = root.left;
    while (curr) {
        if (!isLeaf(curr)) res.push(curr.val);
        curr = curr.left ? curr.left : curr.right;
    }

    function addLeaves(node) {
        if (!node) return;
        if (isLeaf(node)) {
            res.push(node.val);
