class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0, right = 0;
        for (int w : weights) {
            left = Math.max(left, w);
            right += w;
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (feasible(weights, days, mid)) right = mid;
            else left = mid + 1;
        }
        return left;
    }
    private boolean feasible(int[] weights, int days, int cap) {
        int d = 1, curr = 0;
        for (int w : weights) {
            if (curr + w > cap) {
                d++;
                curr = 0;
            }
            curr += w;
        }
        return d <= days;
    }
