import java.util.HashSet;
import java.util.Set;

class Solution {
    private Set<Integer>[][] memo;

    public boolean possiblyEquals(String s1, String s2) {
        int n1 = s1.length(), n2 = s2.length();
        memo = new HashSet[n1 + 1][n2 + 1];
        for (int i = 0; i <= n1; i++) {
            for (int j = 0; j <= n2; j++) {
                memo[i][j] = new HashSet<>();
            }
        }
        return dfs(0, 0, 0, s1, s2);
    }

    private boolean dfs(int i, int j, int diff, String s1, String s2) {
        int n1 = s1.length(), n2 = s2.length();
        if (i == n1 && j == n2) return diff == 0;
        if (memo[i][j].contains(diff)) return false;

        if (diff < 0 && i < n1 && !Character.isDigit(s1.charAt(i))) {
            if (dfs(i + 1, j, diff + 1, s1, s2)) return true;
        } else if (diff > 0 && j < n2 && !Character.isDigit(s2.charAt(j))) {
            if (dfs(i, j + 1, diff - 1, s1, s2)) return true;
        } else if (diff == 0 && i < n1 && j < n2 && !Character.isDigit(s1.charAt(i)) && !Character.isDigit(s2.charAt(j))) {
            if (s1.charAt(i) == s2.charAt(j) && dfs(i + 1, j + 1, 0, s1, s2)) return true;
        }

        if (i < n1 && Character.isDigit(s1.charAt(i))) {
            int num = 0;
            for (int k = i; k < Math.min(i + 3, n1); k++) {
                if (!Character.isDigit(s1.charAt(k))) break;
                num = num * 10 + (s1.charAt(k) - '0');
                if (dfs(k + 1, j, diff + num, s1, s2)) return true;
            }
        }

        if (j < n2 && Character.isDigit(s2.charAt(j))) {
            int num = 0;
            for (int k = j; k < Math.min(j + 3, n2); k++) {
                if (!Character.isDigit(s2.charAt(k))) break;
                num = num * 10 + (s2.charAt(k) - '0');
                if (dfs(i, k + 1, diff - num, s1, s2)) return true;
            }
        }

        memo[i][j].add(diff);
        return false;
    }
}

/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var possiblyEquals = function(s1, s2) {
    const memo = new Map();

    function dfs(i, j, diff) {
        if (i === s1.length && j === s2.length) return diff === 0;
        const key = `${i},${j},${diff}`;
        if (memo.has(key)) return memo.get(key);

        if (diff < 0 && i < s1.length && !/\d/.test(s1[i])) {
            if (dfs(i + 1, j, diff + 1)) {
                memo.set(key, true);
                return true;
            }
        } else if (diff > 0 && j < s2.length && !/\d/.test(s2[j])) {
            if (dfs(i, j + 1, diff - 1)) {
                memo.set(key, true);
                return true;
            }
        } else if (diff === 0 && i < s1.length && j < s2.length && !/\d/.test(s1[i]) && !/\d/.test(s2[j])) {
            if (s1[i] === s2[j] && dfs(i + 1, j + 1, 0)) {
                memo.set(key, true);
                return true;
            }
        }

        if (i < s1.length && /\d/.test(s1[i])) {
            let num = 0;
            for (let k = i; k < Math.min(i + 3, s1.length); k++) {
                if (!/\d/.test(s1[k])) break;
                num = num * 10 + Number(s1[k]);
                if (dfs(k + 1, j, diff + num)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }

        if (j < s2.length && /\d/.test(s2[j])) {
            let num = 0;
            for (let k = j; k < Math.min(j + 3, s2.length); k++) {
                if (!/\d/.test(s2[k])) break;
                num = num * 10 + Number(s2[k]);
                if (dfs(i, k + 1, diff - num)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }

        memo.set(key, false);
        return false;
    }

    return dfs(0, 0, 0);
};

