public:
    bool hasValidPath(std::vector<std::vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        std::vector<std::vector<std::vector<int>>> ports = {
            {}, // 0 unused
            {{0, 1}, {0, -1}}, // 1: right, left
            {{-1, 0}, {1, 0}}, // 2: up, down
            {{0, -1}, {1, 0}}, // 3: left, down
            {{0, 1}, {1, 0}},  // 4: right, down
            {{0, -1}, {-1, 0}},// 5: left, up
            {{0, 1}, {-1, 0}}  // 6: right, up
        };
        std::vector<std::vector<bool>> visited(R, std::vector<bool>(C, false));
        std::queue<std::pair<int, int>> q;
        q.push({0, 0});
        visited[0][0] = true;
        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();
            if (r == R - 1 && c == C - 1) return true;
            for (const auto& d : ports[grid[r][c]]) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {
                    bool connectsBack = false;
                    for (const auto& back : ports[grid[nr][nc]]) {
                        if (back[0] == -d[0] && back[1] == -d[1]) {
                            connectsBack = true;
                            break;
                        }
                    }
                    if (connectsBack) {
                        visited[nr][nc] = true;
                        q.push({nr, nc});
                    }
                }
            }
        }
        return false;
    }
};

