        TreeNode* node = new TreeNode(val);
        TreeNode* parent = dq.front();
        if (!parent->left) {
            parent->left = node;
        } else {
            parent->right = node;
            dq.pop_front();
        }
        dq.push_back(node);
        return parent->val;
    }

