    this.root = root;
    this.dq = [];
    const q = [root];
    while (q.length > 0) {
        const curr = q.shift();
        if (!curr.left || !curr.right) {
            this.dq.push(curr);
        }
        if (curr.left) q.push(curr.left);
        if (curr.right) q.push(curr.right);
    }
};

/** 
