    if (!parent.left) {
        parent.left = node;
    } else {
        parent.right = node;
        this.dq.shift();
    }
    this.dq.push(node);
    return parent.val;
};

/**
 * @return {TreeNode}
 */
CBTInserter.prototype.get_root = function() {
    return this.root;
};

