class Solution {
public:
    int containVirus(vector<vector<int>>& isInfected) {
        int m = isInfected.size(), n = isInfected[0].size();
        int totalWalls = 0;
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (true) {
            vector<vector<bool>> visited(m, vector<bool>(n, false));
            vector<vector<pair<int, int>>> regions;
            vector<set<pair<int, int>>> threats;
            vector<int> wallsNeeded;

            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (isInfected[r][c] == 1 && !visited[r][c]) {
                        vector<pair<int, int>> region;
                        set<pair<int, int>> threat;
                        int walls = 0;
                        vector<pair<int, int>> stk = {{r, c}};
                        visited[r][c] = true;
                        while (!stk.empty()) {
                            auto [cr, cc] = stk.back();
                            stk.pop_back();
                            region.push_back({cr, cc});
                            for (auto& dir : dirs) {
                                int nr = cr + dir[0], nc = cc + dir[1];
                                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                                    if (isInfected[nr][nc] == 1 && !visited[nr][nc]) {
                                        visited[nr][nc] = true;
                                        stk.push_back({nr, nc});
                                    } else if (isInfected[nr][nc] == 0) {
                                        threat.insert({nr, nc});
                                        walls++;
                                    }
                                }
                            }
                        }
                        regions.push_back(region);
                        threats.push_back(threat);
                        wallsNeeded.push_back(walls);
                    }
                }
            }

            if (regions.empty()) break;
            int idx = -1, maxThreat = 0;
            for (int i = 0; i < (int)threats.size(); i++) {
                if ((int)threats[i].size() > maxThreat) {
                    maxThreat = threats[i].size();
                    idx = i;
                }
            }
            if (idx == -1) break;

            totalWalls += wallsNeeded[idx];
            for (auto& [r, c] : regions[idx]) isInfected[r][c] = 2;
            for (int i = 0; i < (int)regions.size(); i++) {
                if (i != idx) {
                    for (auto& [r, c] : threats[i]) isInfected[r][c] = 1;
                }
            }
        }
        return totalWalls;
    }
};

class Solution {
    public int containVirus(int[][] isInfected) {
        int m = isInfected.length, n = isInfected[0].length;
        int totalWalls = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (true) {
            boolean[][] visited = new boolean[m][n];
            List<List<int[]>> regions = new ArrayList<>();
            List<Set<Integer>> threats = new ArrayList<>();
            List<Integer> wallsNeeded = new ArrayList<>();

            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (isInfected[r][c] == 1 && !visited[r][c]) {
                        List<int[]> region = new ArrayList<>();
                        Set<Integer> threat = new HashSet<>();
                        int walls = 0;
                        Deque<int[]> stk = new ArrayDeque<>();
                        stk.push(new int[]{r, c});
                        visited[r][c] = true;
                        while (!stk.isEmpty()) {
                            int[] curr = stk.pop();
                            int cr = curr[0], cc = curr[1];
                            region.add(new int[]{cr, cc});
                            for (int[] dir : dirs) {
                                int nr = cr + dir[0], nc = cc + dir[1];
                                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                                    if (isInfected[nr][nc] == 1 && !visited[nr][nc]) {
                                        visited[nr][nc] = true;
                                        stk.push(new int[]{nr, nc});
                                    } else if (isInfected[nr][nc] == 0) {
                                        threat.add(nr * n + nc);
                                        walls++;
                                    }
                                }
                            }
                        }
                        regions.add(region);
                        threats.add(threat);
                        wallsNeeded.add(walls);
                    }
                }
            }

            if (regions.isEmpty()) break;
            int idx = -1, maxThreat = 0;
            for (int i = 0; i < threats.size(); i++) {
                if (threats.get(i).size() > maxThreat) {
                    maxThreat = threats.get(i).size();
                    idx = i;
                }
            }
            if (idx == -1) break;

            totalWalls += wallsNeeded.get(idx);
            for (int[] p : regions.get(idx)) isInfected[p[0]][p[1]] = 2;
            for (int i = 0; i < regions.size(); i++) {
                if (i != idx) {
                    for (int code : threats.get(i)) isInfected[code / n][code % n] = 1;
                }
            }
        }
        return totalWalls;
    }
}

var containVirus = function(isInfected) {
    const m = isInfected.length, n = isInfected[0].length;
    let totalWalls = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    while (true) {
        const visited = Array.from({ length: m }, () => new Array(n).fill(false));
        const regions = [];
        const threats = [];
        const wallsNeeded = [];

        for (let r = 0; r < m; r++) {
            for (let c = 0; c < n; c++) {
                if (isInfected[r][c] === 1 && !visited[r][c]) {
                    const region = [];
                    const threat = new Set();
                    let walls = 0;
                    const stk = [[r, c]];
                    visited[r][c] = true;
                    while (stk.length > 0) {
                        const [cr, cc] = stk.pop();
                        region.push([cr, cc]);
                        for (const [dr, dc] of dirs) {
                            const nr = cr + dr, nc = cc + dc;
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                                if (isInfected[nr][nc] === 1 && !visited[nr][nc]) {
                                    visited[nr][nc] = true;
                                    stk.push([nr, nc]);
                                } else if (isInfected[nr][nc] === 0) {
                                    threat.add(`${nr},${nc}`);
                                    walls++;
                                }
                            }
                        }
                    }
                    regions.push(region);
                    threats.push(threat);
                    wallsNeeded.push(walls);
                }
            }
        }

        if (regions.length === 0) break;
        let idx = -1, maxThreat = 0;
        for (let i = 0; i < threats.length; i++) {
            if (threats[i].size > maxThreat) {
                maxThreat = threats[i].size;
                idx = i;
            }
        }
        if (idx === -1) break;

        totalWalls += wallsNeeded[idx];
        for (const [r, c] of regions[idx]) isInfected[r][c] = 2;
        for (let i = 0; i < regions.length; i++) {
            if (i !== idx) {
                for (const pos of threats[i]) {
                    const [r, c] = pos.split(',').map(Number);
                    isInfected[r][c] = 1;
                }
            }
        }
    }
    return totalWalls;
};

