import java.util.*;

class Solution {
    private int rev(int x) {
        int r = 0;
        while (x > 0) {
            r = r * 10 + x % 10;
            x /= 10;
        }
        return r;
    }

    public int countNicePairs(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        long ans = 0, MOD = 1_000_000_007L;
        for (int x : nums) {
            int diff = x - rev(x);
            int prev = count.getOrDefault(diff, 0);
            ans = (ans + prev) % MOD;
            count.put(diff, prev + 1);
        }
        return (int)ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var countNicePairs = function(nums) {
    const rev = (x) => {
        let r = 0;
        while (x > 0) {
            r = r * 10 + (x % 10);
            x = Math.floor(x / 10);
        }
        return r;
    };

    const MOD = 1000000007n;
    const count = new Map();
    let ans = 0n;
    for (const x of nums) {
        const diff = x - rev(x);
        const prev = BigInt(count.get(diff) || 0);
        ans = (ans + prev) % MOD;
        count.set(diff, Number(prev) + 1);
    }
    return Number(ans);
};

