        for (int i = (int)nums.size() - 1; i >= 0; i--) {
            int rank = lower_bound(sorted_vals.begin(), sorted_vals.end(), nums[i]) - sorted_vals.begin() + 1;
            res[i] = query(rank - 1);
            update(rank, 1);
        }
        return res;
    }
