    int countLessEqual(const vector<int>& nums, int k) {
        TrieNode* root = new TrieNode();
        int total = 0;
        for (int num : nums) {
            TrieNode* node = root;
            int ans = 0;
            for (int bit = 15; bit >= 0; --bit) {
                if (!node) break;
                int b = (num >> bit) & 1;
                int kb = (k >> bit) & 1;
