      s = (s + tree[idx]) % mod;
      idx -= idx & (-idx);
    }
    return s;
  }

  function update(idx, val) {
    while (idx < tree.length) {
      tree[idx] = (tree[idx] + val) % mod;
      idx += idx & (-idx);
    }
  }

  update(offset, 1);
  let currPref = 0;
  let ans = 0;
  for (const x of nums) {
    currPref += x === 1 ? 1 : -1;
    ans = (ans + query(currPref + offset - 1)) % mod;
    update(currPref + offset, 1);
  }
  return ans;
};

