class Solution {
    vector<int> maxSingle(const vector<int>& nums, int count) {
        vector<int> stack;
        int drop = nums.size() - count;
        for (int x : nums) {
            while (drop > 0 && !stack.empty() && stack.back() < x) {
                stack.pop_back();
                drop--;
            }
            stack.push_back(x);
        }
        stack.resize(count);
        return stack;
    }
    bool greaterVec(const vector<int>& a, int i, const vector<int>& b, int j) {
        while (i < (int)a.size() && j < (int)b.size() && a[i] == b[j]) {
            i++; j++;
        }
        return j == (int)b.size() || (i < (int)a.size() && a[i] > b[j]);
    }
    vector<int> merge(const vector<int>& a, const vector<int>& b) {
        vector<int> res;
        int i = 0, j = 0;
        while (i < (int)a.size() || j < (int)b.size()) {
            if (greaterVec(a, i, b, j)) {
                res.push_back(a[i++]);
            } else {
                res.push_back(b[j++]);
            }
        }
        return res;
    }
public:
    vector<int> maxNumber(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<int> best;
        int m = nums1.size(), n = nums2.size();
        for (int i = max(0, k - n); i <= min(k, m); i++) {
            auto cand = merge(maxSingle(nums1, i), maxSingle(nums2, k - i));
            if (best.empty() || greaterVec(cand, 0, best, 0)) {
                best = cand;
            }
        }
        return best;
    }
};

class Solution {
    public int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int[] best = new int[k];
        int m = nums1.length, n = nums2.length;
        boolean first = true;
        for (int i = Math.max(0, k - n); i <= Math.min(k, m); i++) {
            int[] cand = merge(maxSingle(nums1, i), maxSingle(nums2, k - i), k);
            if (first || greater(cand, 0, best, 0)) {
                best = cand;
                first = false;
            }
        }
        return best;
    }
    private int[] maxSingle(int[] nums, int count) {
        int[] stack = new int[count];
        int top = -1, drop = nums.length - count;
        for (int x : nums) {
            while (drop > 0 && top >= 0 && stack[top] < x) {
                top--;
                drop--;
            }
            if (top < count - 1) stack[++top] = x;
            else drop--;
        }
        return stack;
    }
    private int[] merge(int[] a, int[] b, int k) {
        int[] res = new int[k];
        int i = 0, j = 0, idx = 0;
        while (idx < k) {
            if (greater(a, i, b, j)) res[idx++] = a[i++];
            else res[idx++] = b[j++];
        }
        return res;
    }
    private boolean greater(int[] a, int i, int[] b, int j) {
        while (i < a.length && j < b.length && a[i] == b[j]) {
            i++; j++;
        }
        return j == b.length || (i < a.length && a[i] > b[j]);
    }
}

