var numDecodings = function(s) {
    const mod = 1000000007n;
    let dp0 = 1n, dp1 = 0n;
    if (s[0] === '*') dp1 = 9n;
    else if (s[0] !== '0') dp1 = 1n;

    for (let i = 1; i < s.length; i++) {
        let dp2 = 0n;
        const c1 = s[i - 1], c2 = s[i];

        if (c2 === '*') dp2 = (dp2 + 9n * dp1) % mod;
        else if (c2 !== '0') dp2 = (dp2 + dp1) % mod;

        if (c1 === '*') {
            if (c2 === '*') dp2 = (dp2 + 15n * dp0) % mod;
            else if (c2 >= '0' && c2 <= '6') dp2 = (dp2 + 2n * dp0) % mod;
            else dp2 = (dp2 + dp0) % mod;
        } else if (c1 === '1') {
            if (c2 === '*') dp2 = (dp2 + 9n * dp0) % mod;
            else dp2 = (dp2 + dp0) % mod;
        } else if (c1 === '2') {
            if (c2 === '*') dp2 = (dp2 + 6n * dp0) % mod;
            else if (c2 >= '0' && c2 <= '6') dp2 = (dp2 + dp0) % mod;
        }

        dp0 = dp1;
        dp1 = dp2;
    }
    return Number(dp1);
};

