    let size = 0n;
    for (const c of s) {
        if (/\d/.test(c)) size *= BigInt(c);
        else size += 1n;
    }
    let bk = BigInt(k);
    for (let i = s.length - 1; i >= 0; i--) {
        const c = s[i];
        bk %= size;
        if (bk === 0n && /[a-z]/.test(c)) return c;
        if (/\d/.test(c)) size /= BigInt(c);
        else size -= 1n;
    }
    return "";
