import java.util.*;

class Solution {
    public int maxDepthBST(int[] order) {
        TreeMap<Integer, Integer> depth = new TreeMap<>();
        int maxD = 0;

        for (int x : order) {
            Integer lower = depth.lowerKey(x);
            Integer higher = depth.higherKey(x);
            int predD = lower != null ? depth.get(lower) : 0;
            int succD = higher != null ? depth.get(higher) : 0;
            int d = 1 + Math.max(predD, succD);
            depth.put(x, d);
            maxD = Math.max(maxD, d);
        }
        return maxD;
    }
}

/**
 * @param {number[]} order
 * @return {number}
 */
var maxDepthBST = function(order) {
    const inserted = [];
    const depth = new Map();
    let maxD = 0;

    for (let i = 0; i < order.length; ++i) {
        const x = order[i];
        let l = 0, r = inserted.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (inserted[mid] < x) l = mid + 1;
            else r = mid;
        }

        const predD = l > 0 ? depth.get(inserted[l - 1]) : 0;
        const succD = l < inserted.length ? depth.get(inserted[l]) : 0;
        const d = 1 + Math.max(predD, succD);
        depth.set(x, d);
        if (d > maxD) maxD = d;
        inserted.splice(l, 0, x);
    }
    return maxD;
};

class Solution {
public:
    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        map<long long, long long> diff;
        for (auto& s : segments) {
            diff[s[0]] += s[2];
            diff[s[1]] -= s[2];
        }
        vector<vector<long long>> ans;
        long long currColor = 0, prev = 0;
        for (auto& [pt, delta] : diff) {
            if (currColor > 0 && pt > prev) {
                ans.push_back({prev, pt, currColor});
            }
            currColor += delta;
            prev = pt;
        }
        return ans;
    }
