class ExprNode {
    String val;
    ExprNode left, right;
    ExprNode(String val) { this.val = val; }
    ExprNode(String val, ExprNode left, ExprNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
    public int evaluate() {
        if (Character.isDigit(val.charAt(0))) {
            return Integer.parseInt(val);
        }
        int l = left.evaluate();
        int r = right.evaluate();
        if (val.equals("+")) return l + r;
        if (val.equals("-")) return l - r;
        if (val.equals("*")) return l * r;
        if (val.equals("/")) return l / r;
        return 0;
    }
