        const l = this.left.evaluate();
        const r = this.right.evaluate();
        if (this.val === '+') return l + r;
        if (this.val === '-') return l - r;
        if (this.val === '*') return l * r;
        if (this.val === '/') return Math.trunc(l / r);
        return 0;
    }
}

