        const idx = path.lastIndexOf('/');
        const parent = path.substring(0, idx);
        if (!this.paths.has(parent)) return false;
        this.paths.set(path, value);
        return true;
    }
    get(path) {
        return this.paths.has(path) ? this.paths.get(path) : -1;
    }
