class FileSystem {
    FSNode* root;
    vector<string> splitPath(const string& path) {
        vector<string> parts;
        stringstream ss(path);
        string part;
        while (getline(ss, part, '/')) {
            if (!part.empty()) parts.push_back(part);
        }
        return parts;
    }
public:
    FileSystem() {
        root = new FSNode();
    }

    vector<string> ls(string path) {
        FSNode* curr = root;
        vector<string> parts = splitPath(path);
        for (const string& p : parts) {
            curr = curr->children[p];
        }
        if (curr->isFile) return {parts.back()};
        vector<string> res;
        for (auto& pair : curr->children) res.push_back(pair.first);
        return res;
    }

    void mkdir(string path) {
        FSNode* curr = root;
        for (const string& p : splitPath(path)) {
            if (!curr->children.count(p)) curr->children[p] = new FSNode();
            curr = curr->children[p];
        }
    }

    void addContentToFile(string filePath, string content) {
        FSNode* curr = root;
        for (const string& p : splitPath(filePath)) {
            if (!curr->children.count(p)) curr->children[p] = new FSNode();
            curr = curr->children[p];
        }
        curr->isFile = true;
        curr->content += content;
    }

    string readContentFromFile(string filePath) {
        FSNode* curr = root;
        for (const string& p : splitPath(filePath)) {
            curr = curr->children[p];
        }
        return curr->content;
    }
