    for (const ch of sentence) {
        if (!curr.children.has(ch)) {
            curr.children.set(ch, new TrieNode());
        }
        curr = curr.children.get(ch);
        curr.counts.set(sentence, (curr.counts.get(sentence) || 0) + count);
    }
