        curr = curr.children.get(ch);
    }
    const entries = Array.from(curr.counts.entries());
    entries.sort((a, b) => {
        if (a[1] !== b[1]) return b[1] - a[1];
        return a[0].localeCompare(b[0]);
    });
    return entries.slice(0, 3).map(e => e[0]);
