class ExamRoom {
    int n;
    vector<int> seats;
public:
    ExamRoom(int n) : n(n) {}

    int seat() {
        if (seats.empty()) {
            seats.push_back(0);
            return 0;
        }
        int max_dist = seats[0];
        int best_seat = 0;
        for (size_t i = 0; i + 1 < seats.size(); ++i) {
            int prev = seats[i];
            int nxt = seats[i + 1];
            int dist = (nxt - prev) / 2;
            if (dist > max_dist) {
                max_dist = dist;
                best_seat = prev + dist;
            }
        }
        if (n - 1 - seats.back() > max_dist) {
            best_seat = n - 1;
        }
        auto it = lower_bound(seats.begin(), seats.end(), best_seat);
        seats.insert(it, best_seat);
        return best_seat;
    }

    void leave(int p) {
        auto it = find(seats.begin(), seats.end(), p);
        if (it != seats.end()) seats.erase(it);
    }
};

import java.util.*;

class ExamRoom {
    private int n;
    private List<Integer> seats;

    public ExamRoom(int n) {
        this.n = n;
        this.seats = new ArrayList<>();
    }

    public int seat() {
        if (seats.isEmpty()) {
            seats.add(0);
            return 0;
        }
        int maxDist = seats.get(0);
        int bestSeat = 0;
        for (int i = 0; i < seats.size() - 1; i++) {
            int prev = seats.get(i);
            int nxt = seats.get(i + 1);
            int dist = (nxt - prev) / 2;
            if (dist > maxDist) {
                maxDist = dist;
                bestSeat = prev + dist;
            }
        }
        if (n - 1 - seats.get(seats.size() - 1) > maxDist) {
            bestSeat = n - 1;
        }
        int idx = Collections.binarySearch(seats, bestSeat);
        if (idx < 0) idx = -idx - 1;
        seats.add(idx, bestSeat);
        return bestSeat;
    }

    public void leave(int p) {
        seats.remove((Integer) p);
    }
}

