                    pq.push([d + w, v]);
                }
            }
        }
        return count;
    }
    let minCount = Infinity, bestCity = -1;
    for (let i = 0; i < n; i++) {
        const count = getReachable(i);
        if (count <= minCount) {
            minCount = count;
            bestCity = i;
        }
    }
