class Solution {
public:
    int maxEqualRowsAfterFlips(vector<vector<int>>& matrix) {
        unordered_map<string, int> counts;
        int max_val = 0;
        for (const auto& row : matrix) {
            string canonical = "";
            int flip = row[0];
            for (int x : row) {
                canonical.push_back((x ^ flip) ? '1' : '0');
            }
            max_val = max(max_val, ++counts[canonical]);
        }
        return max_val;
