private:
    bool dfs(const string& s, unordered_map<string, bool>& memo) {
        if (memo.count(s)) return memo[s];
        int n = s.size();
        for (int i = 0; i < n - 1; ++i) {
            if (s[i] == '+' && s[i + 1] == '+') {
                string nextState = s;
                nextState[i] = '-';
                nextState[i + 1] = '-';
                if (!dfs(nextState, memo)) {
                    return memo[s] = true;
                }
            }
        }
        return memo[s] = false;
    }
