        if (memo.containsKey(s)) return memo.get(s);
        char[] arr = s.toCharArray();
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] == '+' && arr[i + 1] == '+') {
                arr[i] = '-';
                arr[i + 1] = '-';
                String nextState = new String(arr);
                boolean opponentWins = dfs(nextState, memo);
                arr[i] = '+';
                arr[i + 1] = '+';
                if (!opponentWins) {
                    memo.put(s, true);
                    return true;
                }
            }
        }
        memo.put(s, false);
        return false;
    }
}

