    let rem = num % den;
    if (rem === 0) return res;
    res += ".";
    const seen = new Map();
    while (rem !== 0) {
        if (seen.has(rem)) {
            const idx = seen.get(rem);
            res = res.slice(0, idx) + "(" + res.slice(idx) + ")";
            break;
        }
        seen.set(rem, res.length);
        rem *= 10;
        res += Math.floor(rem / den);
        rem %= den;
    }
    return res;
