        q = deque([id])
        visited = {id}
        cur_level = 0
        while q and cur_level < level:
            for _ in range(len(q)):
                u = q.popleft()
                for v in friends[u]:
                    if v not in visited:
                        visited.add(v)
                        q.append(v)
            cur_level += 1
        counts = Counter()
        for friend in q:
            for vid in watchedVideos[friend]:
                counts[vid] += 1
        return sorted(counts.keys(), key=lambda x: (counts[x], x))

