    }
public:
    string toGoatLatin(string sentence) {
        stringstream ss(sentence);
        string w, res = "";
        int idx = 1;
        while (ss >> w) {
            if (idx > 1) res += " ";
            if (isVowel(w[0])) {
                res += w + "ma";
            } else {
                res += w.substr(1) + w[0] + "ma";
            }
            res += string(idx, 'a');
