class Solution {
    private int[] parent;
    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        parent = new int[n + 1];
        for (int i = 0; i <= n; ++i) parent[i] = i;
        if (threshold == 0) {
            List<Boolean> res = new ArrayList<>();
            for (int i = 0; i < queries.length; ++i) res.add(true);
            return res;
        }
        for (int d = threshold + 1; d <= n; ++d) {
            for (int mult = 2 * d; mult <= n; mult += d) {
                union(d, mult);
            }
        }
        List<Boolean> ans = new ArrayList<>();
        for (int[] q : queries) {
            ans.add(find(q[0]) == find(q[1]));
        }
        return ans;
    }
}

/**
 * @param {number} n
 * @param {number} threshold
 * @param {number[][]} queries
 * @return {boolean[]}
 */
var areConnected = function(n, threshold, queries) {
    const parent = Array.from({ length: n + 1 }, (_, i) => i);
    function find(x) {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }
    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent[rx] = ry;
    }
    if (threshold === 0) {
        return queries.map(() => true);
    }
    for (let d = threshold + 1; d <= n; ++d) {
        for (let mult = 2 * d; mult <= n; mult += d) {
            union(d, mult);
        }
    }
    return queries.map(([u, v]) => find(u) === find(v));
};

