public:
    std::string toHexspeak(std::string num) {
        long long n = std::stoll(num);
        std::stringstream ss;
        ss << std::hex << std::uppercase << n;
        std::string h = ss.str();
        std::string res = "";
        for (char ch : h) {
            if (ch == '0') res += 'O';
            else if (ch == '1') res += 'I';
            else if (ch >= 'A' && ch <= 'F') res += ch;
            else return "ERROR";
        }
        return res;
    }
};

