class Solution {
public:
    int rob(vector<int>& nums) {
        if (nums.size() == 1) return nums[0];
        auto robLinear = [&](int l, int r) {
            int prev2 = 0, prev1 = 0;
            for (int i = l; i <= r; ++i) {
                int curr = max(prev1, prev2 + nums[i]);
                prev2 = prev1;
                prev1 = curr;
            }
            return prev1;
        };
        int n = nums.size();
        return max(robLinear(0, n - 2), robLinear(1, n - 1));
    }
};

