        for (int i = 0; i < s.length; i++) {
            lookup.putIfAbsent(s[i], i);
        }
        int[] res = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            res[i] = lookup.get(nums[i]);
        }
        return res;
    }
