        ['&lt;', '<'],
        ['&frasl;', '/']
    ];
    const res = [];
    let i = 0;
    while (i < text.length) {
        let matched = false;
        if (text[i] === '&') {
            for (const [ent, ch] of entities) {
                if (text.startsWith(ent, i)) {
                    res.push(ch);
                    i += ent.length;
                    matched = true;
                    break;
                }
            }
        }
        if (!matched) {
            res.push(text[i++]);
        }
    }
    return res.join('');
