class Solution {
public:
    std::string sortString(std::string s) {
        std::vector<int> counts(26, 0);
        for (char ch : s) counts[ch - 'a']++;
        std::string res = "";
        int total = s.size();
        while ((int)res.size() < total) {
            for (int i = 0; i < 26; ++i) {
                if (counts[i] > 0) {
                    res += (char)('a' + i);
                    counts[i]--;
                }
            }
            for (int i = 25; i >= 0; --i) {
                if (counts[i] > 0) {
                    res += (char)('a' + i);
                    counts[i]--;
                }
            }
        }
        return res;
    }
};

