    // Insert in sorted order for small k
    let idx = 0;
    while (idx < this.heap.length && this.heap[idx] < val) {
        idx++;
    }
    this.heap.splice(idx, 0, val);
    if (this.heap.length > this.k) {
        this.heap.shift();
    }
    return this.heap[0];
