    unordered_map<int, int> memo;
    int x_val;

    int dp(int t) {
        if (t < x_val) return min(2 * t - 1, 2 * (x_val - t));
        if (memo.count(t)) return memo[t];

        int k = 0;
        long long p = 1;
        while (p * x_val <= t) {
            p *= x_val;
            k++;
        }
        if (t == p) return memo[t] = k - 1;

        int ans = dp(t - p) + k;
        if (p * x_val - t < t) {
            ans = min(ans, dp(p * x_val - t) + k + 1);
        }
        return memo[t] = ans;
