            k++;
        }
        if (t === p) {
            memo.set(t, k - 1);
            return k - 1;
        }

        let ans = dp(t - p) + k;
        if (p * x - t < t) {
            ans = Math.min(ans, dp(p * x - t) + k + 1);
        }
        memo.set(t, ans);
        return ans;
    }

    return dp(target);
};

