#include <string>
#include <unordered_set>
#include <queue>
#include <algorithm>
using namespace std;

class Solution {
public:
    string findLexSmallestString(string s, int a, int b) {
        unordered_set<string> visited;
        queue<string> q;
        visited.insert(s);
        q.push(s);
        string best = s;
        int n = s.size();
        while (!q.empty()) {
            string curr = q.front(); q.pop();
            if (curr < best) best = curr;
            string added = curr;
            for (int i = 1; i < n; i += 2) {
                added[i] = '0' + (added[i] - '0' + a) % 10;
            }
            if (visited.find(added) == visited.end()) {
                visited.insert(added);
                q.push(added);
            }
            string rotated = curr.substr(n - b) + curr.substr(0, n - b);
            if (visited.find(rotated) == visited.end()) {
                visited.insert(rotated);
                q.push(rotated);
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        Set<String> visited = new HashSet<>();
        Queue<String> q = new LinkedList<>();
        visited.add(s);
        q.offer(s);
        String best = s;
        int n = s.length();
        while (!q.isEmpty()) {
            String curr = q.poll();
            if (curr.compareTo(best) < 0) best = curr;
            char[] chars = curr.toCharArray();
            for (int i = 1; i < n; i += 2) {
                chars[i] = (char)('0' + (chars[i] - '0' + a) % 10);
            }
            String added = new String(chars);
            if (!visited.contains(added)) {
                visited.add(added);
                q.offer(added);
            }
            String rotated = curr.substring(n - b) + curr.substring(0, n - b);
            if (!visited.contains(rotated)) {
                visited.add(rotated);
                q.offer(rotated);
            }
        }
        return best;
    }
}

/**
 * @param {string} s
 * @param {number} a
 * @param {number} b
 * @return {string}
 */
var findLexSmallestString = function(s, a, b) {
    const visited = new Set([s]);
    const q = [s];
    let best = s;
    const n = s.length;
    while (q.length > 0) {
        const curr = q.shift();
        if (curr < best) best = curr;
        const arr = curr.split('');
        for (let i = 1; i < n; i += 2) {
            arr[i] = String((Number(arr[i]) + a) % 10);
        }
        const added = arr.join('');
        if (!visited.has(added)) {
            visited.add(added);
            q.push(added);
        }
        const rotated = curr.slice(n - b) + curr.slice(0, n - b);
        if (!visited.has(rotated)) {
            visited.add(rotated);
            q.push(rotated);
        }
    }
    return best;
};

