class Solution:
    def isSubPath(self, head, root) -> bool:
        def match(list_node, tree_node):
            if not list_node:
                return True
            if not tree_node:
                return False
            if list_node.val != tree_node.val:
                return False
            return match(list_node.next, tree_node.left) or match(list_node.next, tree_node.right)
