                if dp[prev_val] == float('inf'):
                    continue
                for val, cnt in groups[i].items():
                    new_val = prev_val ^ val
                    cost = dp[prev_val] + size[i] - cnt
                    if cost < new_dp[new_val]:
                        new_dp[new_val] = cost
            dp = new_dp
        return dp[0]

