                maxS = s.replace(ch, '9');
                break;
            }
        }
        String minS = s;
        if (s.charAt(0) != '1') {
            minS = s.replace(s.charAt(0), '1');
        } else {
            for (int i = 1; i < s.length(); i++) {
                char ch = s.charAt(i);
                if (ch != '0' && ch != '1') {
                    minS = s.replace(ch, '0');
                    break;
