var maxPoints = function(points) {
    const n = points.length;
    if (n <= 2) return n;
    const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
    let maxPts = 0;
    for (let i = 0; i < n; i++) {
        const slopes = new Map();
        for (let j = i + 1; j < n; j++) {
            let dx = points[j][0] - points[i][0];
            let dy = points[j][1] - points[i][1];
            const g = gcd(dx, dy);
            dx = Math.floor(dx / g);
            dy = Math.floor(dy / g);
            if (dx < 0 || (dx === 0 && dy < 0)) {
                dx = -dx;
                dy = -dy;
            }
            const key = `${dx}/${dy}`;
            slopes.set(key, (slopes.get(key) || 0) + 1);
        }
        for (const count of slopes.values()) {
            maxPts = Math.max(maxPts, count + 1);
        }
    }
    return Math.max(maxPts, 1);
};

class MaxStack {
    list<int> dll;
    map<int, vector<list<int>::iterator>> map;
public:
    MaxStack() {}

    void push(int x) {
        dll.push_front(x);
        map[x].push_back(dll.begin());
    }

    int pop() {
        int x = dll.front();
        dll.pop_front();
        map[x].pop_back();
        if (map[x].empty()) map.erase(x);
        return x;
    }

    int top() {
        return dll.front();
    }

    int peekMax() {
        return map.rbegin()->first;
    }

    int popMax() {
        int maxVal = map.rbegin()->first;
        auto it = map[maxVal].back();
        map[maxVal].pop_back();
        if (map[maxVal].empty()) map.erase(maxVal);
