        vector<TreeNode*> stk;
        for (int x : nums) {
            TreeNode* curr = new TreeNode(x);
            while (!stk.empty() && stk.back()->val < x) {
                curr->left = stk.back();
                stk.pop_back();
            }
            if (!stk.empty()) {
                stk.back()->right = curr;
            }
            stk.push_back(curr);
        }
