            int currSum = 0;
            for (int i = 0; i < sz; i++) {
                TreeNode node = q.poll();
                currSum += node.val;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            if (currSum > maxSum) {
                maxSum = currSum;
                bestLevel = level;
            }
            level++;
        }
        return bestLevel;
    }
}

