using namespace std;

class Solution {
public:
    int maximumRequests(int n, vector<vector<int>>& requests) {
        int m = requests.size();
        int ans = 0;
        for (int mask = 0; mask < (1 << m); ++mask) {
            int count = __builtin_popcount(mask);
            if (count <= ans) continue;
            vector<int> delta(n, 0);
            for (int i = 0; i < m; ++i) {
                if (mask & (1 << i)) {
                    delta[requests[i][0]]--;
                    delta[requests[i][1]]++;
                }
            }
            bool ok = true;
            for (int d : delta) {
                if (d != 0) { ok = false; break; }
            }
            if (ok) ans = count;
        }
        return ans;
    }
};

