            int count = Integer.bitCount(mask);
            if (count <= ans) continue;
            int[] delta = new int[n];
            for (int i = 0; i < m; ++i) {
                if ((mask & (1 << i)) != 0) {
                    delta[requests[i][0]]--;
                    delta[requests[i][1]]++;
                }
            }
            boolean ok = true;
            for (int d : delta) {
                if (d != 0) { ok = false; break; }
            }
