                    for (const auto& pt : darts) {
                        double dist2 = (pt[0] - cx)*(pt[0] - cx) + (pt[1] - cy)*(pt[1] - cy);
                        if (dist2 <= r * r + 1e-7) cnt++;
                    }
                    ans = max(ans, cnt);
                }
            }
        }
        return ans;
    }
