 * @param {number} boardingCost
 * @param {number} runningCost
 * @return {number}
 */
var minOperationsMaxProfit = function(customers, boardingCost, runningCost) {
    let waiting = 0, boarded = 0, maxProfit = 0, bestRotations = -1;
    let rotations = 0, i = 0, n = customers.length;
    while (i < n || waiting > 0) {
        if (i < n) {
            waiting += customers[i++];
        }
        const board = Math.min(4, waiting);
        waiting -= board;
        boarded += board;
        rotations++;
        const profit = boarded * boardingCost - rotations * runningCost;
        if (profit > maxProfit) {
            maxProfit = profit;
            bestRotations = rotations;
        }
    }
    return bestRotations;
