public:
    vector<int> maxSumOfThreeSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> W;
        int curr = 0;
        for (int i = 0; i < k; i++) curr += nums[i];
        W.push_back(curr);
        for (int i = k; i < n; i++) {
            curr += nums[i] - nums[i - k];
            W.push_back(curr);
        }

        int m = W.size();
        vector<int> left(m, 0);
        int best = 0;
        for (int i = 0; i < m; i++) {
            if (W[i] > W[best]) best = i;
            left[i] = best;
        }

        vector<int> right(m, 0);
        best = m - 1;
        for (int i = m - 1; i >= 0; i--) {
            if (W[i] >= W[best]) best = i;
            right[i] = best;
        }

        int maxTotal = 0;
        vector<int> ans;
        for (int mid = k; mid < m - k; mid++) {
            int l = left[mid - k], r = right[mid + k];
            int total = W[l] + W[mid] + W[r];
            if (total > maxTotal) {
                maxTotal = total;
                ans = {l, mid, r};
            }
        }
        return ans;
    }
};

