class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        from collections import defaultdict
        counts = defaultdict(int)
        curr_sum = 0
        max_sum = 0
        for i in range(k):
            counts[nums[i]] += 1
            curr_sum += nums[i]
        if len(counts) == k:
            max_sum = curr_sum
        for i in range(k, len(nums)):
            in_val, out_val = nums[i], nums[i - k]
            counts[in_val] += 1
            curr_sum += in_val
            counts[out_val] -= 1
            if counts[out_val] == 0:
                del counts[out_val]
            curr_sum -= out_val
            if len(counts) == k:
                max_sum = max(max_sum, curr_sum)
        return max_sum

