                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[rx] = ry

        for u, v in allowedSwaps:
            union(u, v)

        components = defaultdict(list)
        for i in range(n):
            components[find(i)].append(i)

        diff = 0
        for comp in components.values():
            freq = defaultdict(int)
            for idx in comp:
                freq[source[idx]] += 1
            for idx in comp:
                val = target[idx]
                if freq[val] > 0:
                    freq[val] -= 1
