var connectSticks = function(sticks) {
    // Min heap implementation
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] > heap[i]) {
                [heap[p], heap[i]] = [heap[i], heap[p]];
                i = p;
            } else break;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < heap.length && heap[l] < heap[best]) best = l;
                if (r < heap.length && heap[r] < heap[best]) best = r;
                if (best !== i) {
                    [heap[i], heap[best]] = [heap[best], heap[i]];
                    i = best;
                } else break;
            }
        }
        return top;
    };

    for (const s of sticks) push(s);
    let totalCost = 0;
    while (heap.length > 1) {
        const first = pop();
        const second = pop();
        const cost = first + second;
        totalCost += cost;
        push(cost);
    }
    return totalCost;
};

