        if (i === n) return 0;
        if (memo.has(i)) return memo.get(i);

        let res = Infinity;
        let currLen = -1;
        for (let j = i; j < n; j++) {
            currLen += lens[j] + 1;
            if (currLen > k) break;
            const rowCost = (j === n - 1) ? 0 : (k - currLen) ** 2;
            res = Math.min(res, rowCost + dfs(j + 1));
        }
        memo.set(i, res);
        return res;
    }

