    let res = 1n;
    b = b % m;
    while (e > 0n) {
      if (e & 1n) res = (res * b) % m;
      b = (b * b) % m;
      e >>= 1n;
    }
    return res;
  };

  const ans = (modPow(val, cnt, mod) * (maxVal % mod)) % mod;
  return Number(ans);
