        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (mat[r][c]) start |= (1 << (r * n + c));
            }
        }
        if (start == 0) return 0;
        std::queue<std::pair<int, int>> q;
        q.push({start, 0});
        std::vector<bool> seen(1 << (m * n), false);
        seen[start] = true;
        int dirs[5][2] = {{0, 0}, {1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.empty()) {
            auto [state, steps] = q.front();
            q.pop();
            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    int nxt = state;
                    for (auto& d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                            nxt ^= (1 << (nr * n + nc));
                        }
                    }
                    if (nxt == 0) return steps + 1;
                    if (!seen[nxt]) {
                        seen[nxt] = true;
                        q.push({nxt, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
};

