    vector<int> diffs;
    int minLen;
    int bestMask;

    bool isValid(int mask) {
        for (int d : diffs) {
            if ((mask & d) == 0) return false;
        }
        return true;
    }

    void dfs(int idx, int currMask, int length, bool prevZero) {
        if (length >= minLen) return;
        if (idx == m) {
            if (isValid(currMask)) {
                minLen = length;
                bestMask = currMask;
            }
            return;
        }
        dfs(idx + 1, currMask | (1 << (m - 1 - idx)), length + 1, false);
        dfs(idx + 1, currMask, length + (prevZero ? 0 : 1), true);
    }
