        diffs.clear();
        for (const string& w : dictionary) {
            if ((int)w.size() != m) continue;
            int mask = 0;
            for (int i = 0; i < m; i++) {
                if (target[i] != w[i]) {
                    mask |= (1 << (m - 1 - i));
                }
            }
