class MovingAverage {
private:
    int size;
    queue<int> q;
    double total = 0.0;

public:
    MovingAverage(int size) : size(size) {}

    double next(int val) {
        total += val;
        q.push(val);
        if ((int)q.size() > size) {
            total -= q.front();
            q.pop();
        }
        return total / q.size();
    }
};

import java.util.ArrayDeque;
