class MovingAverage {
    private final int size;
    private final Queue<Integer> q = new ArrayDeque<>();
    private double total = 0.0;

    public MovingAverage(int size) {
        this.size = size;
    }

    public double next(int val) {
        total += val;
        q.add(val);
        if (q.size() > size) {
            total -= q.remove();
        }
        return total / q.size();
    }
}

