                    if (nr == 0 || nr == m - 1 || nc == 0 || nc == n - 1) return d + 1;
                    maze[nr][nc] = '+';
                    q.offer(new int[]{nr, nc, d + 1});
                }
            }
        }
        return -1;
    }
