public:
    int equalCountSubstrings(std::string s, int count) {
        int n = s.size();
        int ans = 0;

        for (int u = 1; u <= 26; ++u) {
            int length = u * count;
            if (length > n) break;

            std::vector<int> freq(26, 0);
            int validChars = 0;

            for (int i = 0; i < n; ++i) {
                int cIn = s[i] - 'a';
                freq[cIn]++;
