                int nkey = nr * n + nc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && parent[nkey] != -1) {
                    int root1 = find(key), root2 = find(nkey);
                    if (root1 != root2) {
                        parent[root1] = root2;
                        count--;
                    }
                }
            }
            res.push_back(count);
