    public int numIslands(char[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        int m = grid.length, n = grid[0].length;
        int count = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == '1') {
                    count++;
                    sink(grid, r, c, m, n);
                }
            }
        }
        return count;
    }

    private void sink(char[][] grid, int r, int c, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] != '1') return;
        grid[r][c] = '0';
        sink(grid, r + 1, c, m, n);
        sink(grid, r - 1, c, m, n);
        sink(grid, r, c + 1, m, n);
        sink(grid, r, c - 1, m, n);
    }
}

