            int idx = -1;
            bool match = true;
            for (char ch : w) {
                const auto& vec = pos[ch - 'a'];
                auto it = upper_bound(vec.begin(), vec.end(), idx);
                if (it == vec.end()) {
                    match = false;
                    break;
                }
                idx = *it;
            }
            memo[w] = match;
            if (match) ans++;
        }
        return ans;
    }
