class Solution:
    def numberOfSets(self, n: int, k: int) -> int:
        MOD = 10**9 + 7
        return math.comb(n + k - 1, 2 * k) % MOD

class Solution {
    long long modPow(long long base, long long exp, long long mod) {
        long long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
public:
    int numberOfSets(int n, int k) {
        long long N = n + k - 1;
        long long R = 2 * k;
        if (R > N) return 0;
        long long MOD = 1e9 + 7;
        long long num = 1, den = 1;
        for (long long i = 1; i <= R; ++i) {
            num = (num * (N - i + 1)) % MOD;
            den = (den * i) % MOD;
        }
        long long ans = (num * modPow(den, MOD - 2, MOD)) % MOD;
        return ans;
    }
};

class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }

    public int numberOfSets(int n, int k) {
        long N = n + k - 1;
        long R = 2L * k;
        if (R > N) return 0;
        long MOD = 1000000007L;
        long num = 1, den = 1;
        for (long i = 1; i <= R; ++i) {
            num = (num * (N - i + 1)) % MOD;
            den = (den * i) % MOD;
        }
        long ans = (num * modPow(den, MOD - 2, MOD)) % MOD;
        return (int)ans;
    }
}

/**
 * @param {number} n
 * @param {number} k
 * @return {number}
 */
var numberOfSets = function(n, k) {
    const N = BigInt(n + k - 1);
    const R = BigInt(2 * k);
    if (R > N) return 0;
    const MOD = 1000000007n;
    function modPow(base, exp, mod) {
        let res = 1n;
        base %= mod;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2n;
        }
        return res;
    }
    let num = 1n, den = 1n;
    for (let i = 1n; i <= R; ++i) {
        num = (num * (N - i + 1n)) % MOD;
        den = (den * i) % MOD;
    }
    const ans = (num * modPow(den, MOD - 2n, MOD)) % MOD;
    return Number(ans);
};

