        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            let res = (arr[i] === arr[j] ? dp[i + 1][j - 1] : Infinity);
            for (let k = i; k < j; k++) {
                res = Math.min(res, dp[i][k] + dp[k + 1][j]);
            }
            dp[i][j] = res;
        }
    }
    return dp[0][n - 1];
};

