            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const cost = Math.max(d, Math.abs(heights[r][c] - heights[nr][nc]));
                if (cost < dist[nr][nc]) {
                    dist[nr][nc] = cost;
                    pq.push([cost, nr, nc]);
                }
            }
        }
    }
    return dist[m - 1][n - 1];
