class Solution {
public:
    ListNode* plusOne(ListNode* head) {
        ListNode dummy(0, head);
        ListNode* notNine = &dummy;
        ListNode* curr = head;
        while (curr) {
            if (curr->val != 9) {
                notNine = curr;
            }
            curr = curr->next;
        }
        notNine->val++;
        curr = notNine->next;
        while (curr) {
            curr->val = 0;
            curr = curr->next;
        }
        if (dummy.val != 0) {
            return new ListNode(dummy.val, head);
        }
        return dummy.next;
    }
};

