            if (curr.val != 9) {
                notNine = curr;
            }
            curr = curr.next;
        }
        notNine.val++;
        curr = notNine.next;
        while (curr != null) {
            curr.val = 0;
            curr = curr.next;
        }
        return dummy.val != 0 ? dummy : dummy.next;
    }
