class Solution {
public:
    vector<int> pourWater(vector<int>& heights, int volume, int k) {
        int n = heights.size();
        for (int v = 0; v < volume; v++) {
            int best = k;
            for (int i = k - 1; i >= 0; i--) {
                if (heights[i] > heights[i + 1]) break;
                if (heights[i] < heights[best]) best = i;
            }
            if (best != k) {
                heights[best]++;
                continue;
            }
            for (int i = k + 1; i < n; i++) {
                if (heights[i] > heights[i - 1]) break;
                if (heights[i] < heights[best]) best = i;
            }
            heights[best]++;
        }
        return heights;
    }
};

class Solution {
    public int[] pourWater(int[] heights, int volume, int k) {
        int n = heights.length;
        for (int v = 0; v < volume; v++) {
            int best = k;
            for (int i = k - 1; i >= 0; i--) {
                if (heights[i] > heights[i + 1]) break;
                if (heights[i] < heights[best]) best = i;
            }
            if (best != k) {
                heights[best]++;
                continue;
            }
            for (int i = k + 1; i < n; i++) {
                if (heights[i] > heights[i - 1]) break;
                if (heights[i] < heights[best]) best = i;
            }
            heights[best]++;
        }
        return heights;
    }
}

var pourWater = function(heights, volume, k) {
    const n = heights.length;
    for (let v = 0; v < volume; v++) {
        let best = k;
        for (let i = k - 1; i >= 0; i--) {
            if (heights[i] > heights[i + 1]) break;
            if (heights[i] < heights[best]) best = i;
        }
        if (best !== k) {
            heights[best]++;
            continue;
        }
        for (let i = k + 1; i < n; i++) {
            if (heights[i] > heights[i - 1]) break;
            if (heights[i] < heights[best]) best = i;
        }
        heights[best]++;
    }
    return heights;
};

