            if (seen.containsKey(mask)) {
                int cycle = seen.get(mask) - n;
                n %= cycle;
                if (n == 0) break;
            }
            seen.put(mask, n);
            if (n > 0) {
                n--;
                int[] next = new int[8];
                for (int i = 1; i < 7; i++) {
