            comb[i][0] = comb[i][i] = 1.0;
            for (int j = 1; j < i; j++) comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
        }
        memset(vis, 0, sizeof(vis));
        auto res = dp(0, 0, 0, 0, balls);
        return res.first / res.second;
