        int idx = 0;
        for (int i = 0; i < n; i++) {
            int cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                sums[idx++] = cur;
            }
        }
        Arrays.sort(sums);
        long ans = 0;
        for (int i = left - 1; i < right; i++) {
            ans = (ans + sums[i]) % MOD;
        }
        return (int) ans;
    }
}

