            pq.pop();
            if (dist[u] != -1) continue;
            dist[u] = d;
            for (auto& [v, w] : adj[u]) {
                if (dist[v] == -1 && d + w + 1 <= maxMoves) {
                    pq.push({d + w + 1, v});
