class Solution {
public:
    string reorderSpaces(string text) {
        int total_spaces = 0;
        for (char c : text) {
            if (c == ' ') total_spaces++;
        }
        stringstream ss(text);
        string word;
        vector<string> words;
        while (ss >> word) {
            words.push_back(word);
        }
        int n = words.size();
        if (n == 1) {
            return words[0] + string(total_spaces, ' ');
        }
        int gap = total_spaces / (n - 1);
        int rem = total_spaces % (n - 1);
        string res = "";
        for (int i = 0; i < n; ++i) {
            res += words[i];
            if (i < n - 1) res += string(gap, ' ');
        }
        res += string(rem, ' ');
        return res;
    }
};

