    tickets.sort((a, b) => (a[1] > b[1] ? -1 : 1));
    for (const [u, v] of tickets) {
        if (!adj.has(u)) adj.set(u, []);
        adj.get(u).push(v);
    }
    const route = [];
    function dfs(airport) {
        const destinations = adj.get(airport) || [];
        while (destinations.length > 0) {
            const nxt = destinations.pop();
            dfs(nxt);
        }
        route.push(airport);
    }
    dfs('JFK');
    return route.reverse();
};

