class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        vector<int> parent(4 * n * n);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto& self, int x) -> int {
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };
        auto unite = [&](int x, int y) {
            int rx = find(find, x), ry = find(find, y);
            if (rx != ry) parent[rx] = ry;
        };
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                int root = 4 * (r * n + c);
                char val = grid[r][c];
                if (val == '/') {
                    unite(root + 0, root + 3);
                    unite(root + 1, root + 2);
                } else if (val == '\\') {
                    unite(root + 0, root + 1);
                    unite(root + 2, root + 3);
                } else {
                    unite(root + 0, root + 1);
                    unite(root + 1, root + 2);
                    unite(root + 2, root + 3);
                }
                if (r + 1 < n) unite(root + 2, 4 * ((r + 1) * n + c) + 0);
                if (c + 1 < n) unite(root + 1, 4 * (r * n + (c + 1)) + 3);
            }
        }
        int count = 0;
        for (int i = 0; i < 4 * n * n; ++i) {
            if (find(find, i) == i) count++;
        }
        return count;
    }
};

