        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '(') st[top++] = i;
            else if (ch == ')') {
                int j = st[--top];
                pairIdx[i] = j;
                pairIdx[j] = i;
            }
