        int[] tails = new int[envelopes.length];
        int size = 0;
        for (int[] e : envelopes) {
            int h = e[1];
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) / 2;
                if (tails[m] < h) l = m + 1;
                else r = m;
            }
            tails[l] = h;
            if (l == size) size++;
        }
        return size;
    }
