    const memo = new Map();
    function dfs(a, b) {
        if (a === b) return true;
        const key = a + '#' + b;
        if (memo.has(key)) return memo.get(key);
        const sa = a.split('').sort().join('');
        const sb = b.split('').sort().join('');
        if (sa !== sb) {
            memo.set(key, false);
            return false;
        }
        const n = a.length;
        for (let i = 1; i < n; i++) {
            if ((dfs(a.slice(0, i), b.slice(0, i)) && dfs(a.slice(i), b.slice(i))) ||
                (dfs(a.slice(0, i), b.slice(n - i)) && dfs(a.slice(i), b.slice(0, n - i)))) {
                memo.set(key, true);
                return true;
            }
        }
        memo.set(key, false);
        return false;
    }
    return dfs(s1, s2);
};

