class SeatManager {
private:
    priority_queue<int, vector<int>, greater<int>> pq;
public:
    SeatManager(int n) {
        for (int i = 1; i <= n; i++) pq.push(i);
    }

    int reserve() {
        int seat = pq.top();
        pq.pop();
        return seat;
    }

    void unreserve(int seatNumber) {
        pq.push(seatNumber);
    }
};

class SeatManager {
    private PriorityQueue<Integer> pq;

    public SeatManager(int n) {
        pq = new PriorityQueue<>();
        for (int i = 1; i <= n; i++) pq.offer(i);
    }

    public int reserve() {
        return pq.poll();
    }

    public void unreserve(int seatNumber) {
        pq.offer(seatNumber);
    }
}

class SeatManager {
  constructor(n) {
    this.minNext = 1;
    this.recycled = [];
  }

  reserve() {
    if (this.recycled.length > 0) {
      this.recycled.sort((a, b) => a - b);
      return this.recycled.shift();
    }
    return this.minNext++;
  }

  unreserve(seatNumber) {
    this.recycled.push(seatNumber);
  }
}

