        q.offer(new int[]{1, 0});

        while (!q.isEmpty()) {
            int[] top = q.poll();
            int node = top[0];
            int currTime = top[1];

            int period = currTime / change;
            if (period % 2 == 1) {
                currTime = (period + 1) * change;
