class Solution {
public:
    string shiftingLetters(string s, vector<int>& shifts) {
        int totalShift = 0;
        int n = s.size();
        for (int i = n - 1; i >= 0; i--) {
            totalShift = (totalShift + shifts[i]) % 26;
            s[i] = (s[i] - 'a' + totalShift) % 26 + 'a';
        }
        return s;
    }
};

