                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 0 && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            reachCount[nr][nc]++;
                            totalDist[nr][nc] += d + 1;
                            q.push([nr, nc, d + 1]);
                        }
                    }
                }
            }
        }
    }
    let ans = Infinity;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 0 && reachCount[r][c] === buildings) {
                ans = Math.min(ans, totalDist[r][c]);
            }
        }
    }
    return ans === Infinity ? -1 : ans;
};

