                if (similar(strs[i], strs[j])) {
                    int rx = find(parent, i), ry = find(parent, j);
                    if (rx != ry) parent[rx] = ry;
                }
            }
        }
        int components = 0;
        for (int i = 0; i < n; i++) if (find(parent, i) == i) components++;
