class Solution {
public:
    string smallestGoodBase(string n) {
        unsigned long long num = stoull(n);
        int maxM = log2(num);

        for (int m = maxM; m >= 2; m--) {
            unsigned long long k = pow(num, 1.0 / m);
            if (k >= 2) {
                unsigned long long sum = 0;
                unsigned long long term = 1;
                bool overflow = false;
                for (int i = 0; i <= m; i++) {
                    sum += term;
                    if (i < m) {
                        if (term > (num / k)) {
                            overflow = true;
                            break;
                        }
                        term *= k;
                    }
                }
                if (!overflow && sum == num) return to_string(k);
            }
        }
        return to_string(num - 1);
    }
};

