            int u = order[i];
            int p = parent[u];
            count[p] += count[u];
            ans[p] += ans[u] + count[u];
        }

        for (int i = 1; i < n; ++i) {
            int u = order[i];
            int p = parent[u];
            ans[u] = ans[p] - count[u] + (n - count[u]);
        }

        return ans;
    }
