    while (count < n) {
        const halfLen = Math.floor((length + 1) / 2);
        const start = 10 ** (halfLen - 1);
        const end = 10 ** halfLen;

        for (let prefix = start; prefix < end; prefix++) {
            const s = String(prefix);
            const rev = s.split('').reverse().join('');
            const fullStr = s + (length % 2 === 1 ? rev.slice(1) : rev);
            const val = BigInt(fullStr);

            if (isPalindromeK(val)) {
                ans += val;
                count++;
                if (count === n) return Number(ans);
            }
        }
        length++;
    }
    return Number(ans);
