public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        vector<string> res;
        vector<string> line;
        int length = 0;
        for (const auto& word : words) {
            if (length + (int)line.size() + (int)word.size() > maxWidth) {
                int spaces = maxWidth - length;
                int slots = max(1, (int)line.size() - 1);
                for (int i = 0; i < spaces; i++) {
                    line[i % slots] += " ";
                }
                string s = "";
                for (const auto& w : line) s += w;
                res.push_back(s);
                line.clear();
                length = 0;
            }
            line.push_back(word);
            length += word.size();
        }
        string lastLine = "";
        for (size_t i = 0; i < line.size(); i++) {
            if (i > 0) lastLine += " ";
            lastLine += line[i];
        }
        while ((int)lastLine.size() < maxWidth) lastLine += " ";
        res.push_back(lastLine);
        return res;
    }
};

