var getSkyline = function(buildings) {
    const events = [];
    for (const [L, R, H] of buildings) {
        events.push([L, -H, R]);
        events.push([R, 0, 0]);
    }
    events.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
    const heap = [[0, Infinity]];
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = Math.floor((i - 1) / 2);
            if (heap[p][0] >= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < heap.length && heap[l][0] > heap[best][0]) best = l;
                if (r < heap.length && heap[r][0] > heap[best][0]) best = r;
                if (best === i) break;
                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }
        return top;
    };
    const res = [];
    let prevH = 0;
    for (const [x, negH, r] of events) {
        if (negH !== 0) push([-negH, r]);
        while (heap[0][1] <= x) pop();
        const currH = heap[0][0];
        if (currH !== prevH) {
            res.push([x, currH]);
            prevH = currH;
        }
    }
    return res;
};

from collections import deque

class Solution:
    def networkBecomesIdle(self, edges: list[list[int]], patience: list[int]) -> int:
        n = len(patience)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            curr = q.popleft()
            for nxt in adj[curr]:
                if dist[nxt] == -1:
                    dist[nxt] = dist[curr] + 1
                    q.append(nxt)

        max_time = 0
        for i in range(1, n):
            round_trip = 2 * dist[i]
            p = patience[i]
            last_sent = ((round_trip - 1) // p) * p
            last_received = last_sent + round_trip
            if last_received > max_time:
                max_time = last_received
        return max_time + 1

