class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(0);

        while (!q.isEmpty()) {
            int curr = q.poll();
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.offer(nxt);
                }
            }
        }

        int maxTime = 0;
        for (int i = 1; i < n; i++) {
            int roundTrip = 2 * dist[i];
            int p = patience[i];
            int lastSent = ((roundTrip - 1) / p) * p;
            int lastReceived = lastSent + roundTrip;
            if (lastReceived > maxTime) {
                maxTime = lastReceived;
            }
        }
        return maxTime + 1;
    }
}

