        row_ones = sum(board[0])
        col_ones = sum(board[r][0] for r in range(n))
        if row_ones < n // 2 or row_ones > (n + 1) // 2:
            return -1
        if col_ones < n // 2 or col_ones > (n + 1) // 2:
            return -1

