            best_depth = -1
            best_node = -1
            for c in coprimes[val]:
                if history[c]:
                    cand_node, cand_depth = history[c][-1]
                    if cand_depth > best_depth:
                        best_depth = cand_depth
                        best_node = cand_node
            ans[u] = best_node
