class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        def lcm(x, y):
            return (x * y) // math.gcd(x, y)

        ab = lcm(a, b)
        bc = lcm(b, c)
        ac = lcm(a, c)
        abc = lcm(ab, c)

        def count(x):
            return (x // a + x // b + x // c
                    - x // ab - x // bc - x // ac
                    + x // abc)

        low, high = 1, 2 * 10**9
