                for (int i = first[c] + 1; i < last[c]; i++) {
                    int mid = s.charAt(i) - 'a';
                    if (!seen[mid]) {
                        seen[mid] = true;
                        distinct++;
                    }
                }
                ans += distinct;
            }
        }
        return ans;
    }
