class Solution {
public:
    bool isValidPalindrome(std::string s, int k) {
        int n = s.size();
        std::string rev = s;
        std::reverse(rev.begin(), rev.end());
        std::vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            std::vector<int> nxt(n + 1, 0);
            for (int j = 1; j <= n; ++j) {
                if (s[i - 1] == rev[j - 1]) {
                    nxt[j] = dp[j - 1] + 1;
                } else {
                    nxt[j] = std::max(dp[j], nxt[j - 1]);
                }
            }
            dp = std::move(nxt);
        }
        return n - dp[n] <= k;
    }
};

