class Solution:
    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> list[str]:
        hostname = startUrl.split("/")[2]
        visited = {startUrl}
        q = deque([startUrl])

        while q:
            curr = q.popleft()
            for url in htmlParser.getUrls(curr):
                if url.split("/")[2] == hostname and url not in visited:
                    visited.add(url)
