class Solution {
    struct TrieNode {
        TrieNode* children[26] = {};
        string word = "";
    };
    int m, n;
    vector<string> res;

    void dfs(vector<vector<char>>& board, int r, int c, TrieNode* curr) {
        char ch = board[r][c];
        int idx = ch - 'a';
        if (!curr->children[idx]) return;
        curr = curr->children[idx];
        if (!curr->word.empty()) {
            res.push_back(curr->word);
            curr->word = "";
        }

        board[r][c] = '#';
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (auto& d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] != '#') {
                dfs(board, nr, nc, curr);
            }
        }
        board[r][c] = ch;
    }
public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        TrieNode* root = new TrieNode();
        for (const string& w : words) {
            TrieNode* curr = root;
            for (char c : w) {
                int idx = c - 'a';
                if (!curr->children[idx]) curr->children[idx] = new TrieNode();
                curr = curr->children[idx];
            }
            curr->word = w;
        }

        m = board.size();
        n = board[0].size();
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                dfs(board, r, c, root);
            }
        }
        return res;
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null;
    }
    private int m, n;
    private List<String> res = new ArrayList<>();

    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode curr = root;
            for (char c : w.toCharArray()) {
                int idx = c - 'a';
                if (curr.children[idx] == null) curr.children[idx] = new TrieNode();
                curr = curr.children[idx];
            }
            curr.word = w;
        }

        m = board.length;
        n = board[0].length;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                dfs(board, r, c, root);
            }
        }
        return res;
    }

    private void dfs(char[][] board, int r, int c, TrieNode curr) {
        char ch = board[r][c];
        int idx = ch - 'a';
        if (curr.children[idx] == null) return;
        curr = curr.children[idx];
        if (curr.word != null) {
            res.add(curr.word);
            curr.word = null;
        }

        board[r][c] = '#';
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] != '#') {
                dfs(board, nr, nc, curr);
            }
        }
        board[r][c] = ch;
    }
}

