class Solution:
    def wordSquares(self, words: List[str]) -> List[List[str]]:
        n = len(words[0])
        prefix_map = defaultdict(list)
        for w in words:
            for i in range(n + 1):
                prefix_map[w[:i]].append(w)

        res = []
        curr = []

        def backtrack(step: int):
            if step == n:
                res.append(list(curr))
                return
            prefix = "".join(curr[i][step] for i in range(step))
            for candidate in prefix_map.get(prefix, []):
                curr.append(candidate)
                backtrack(step + 1)
                curr.pop()

        for w in words:
            curr.append(w)
            backtrack(1)
            curr.pop()

        return res

class Solution {
    int n;
    unordered_map<string, vector<string>> prefixMap;
    vector<vector<string>> res;
    vector<string> curr;

    void backtrack(int step) {
        if (step == n) {
            res.push_back(curr);
            return;
        }
        string prefix = "";
        for (int i = 0; i < step; i++) {
            prefix += curr[i][step];
        }
        auto it = prefixMap.find(prefix);
        if (it != prefixMap.end()) {
            for (const string& cand : it->second) {
                curr.push_back(cand);
                backtrack(step + 1);
                curr.pop_back();
            }
        }
    }
public:
    vector<vector<string>> wordSquares(vector<string>& words) {
        n = words[0].size();
        prefixMap.clear();
        res.clear();
        curr.clear();

        for (const string& w : words) {
            for (int i = 0; i <= n; i++) {
                prefixMap[w.substr(0, i)].push_back(w);
            }
        }

        for (const string& w : words) {
            curr.push_back(w);
            backtrack(1);
            curr.pop_back();
        }
        return res;
    }
};

class Solution {
    private int n;
    private Map<String, List<String>> prefixMap = new HashMap<>();
    private List<List<String>> res = new ArrayList<>();
    private List<String> curr = new ArrayList<>();

    private void backtrack(int step) {
        if (step == n) {
            res.add(new ArrayList<>(curr));
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < step; i++) {
            sb.append(curr.get(i).charAt(step));
        }
        String prefix = sb.toString();
        List<String> cands = prefixMap.get(prefix);
        if (cands != null) {
            for (String cand : cands) {
                curr.add(cand);
                backtrack(step + 1);
                curr.remove(curr.size() - 1);
            }
        }
    }

    public List<List<String>> wordSquares(String[] words) {
        n = words[0].length();
        prefixMap.clear();
        res.clear();
        curr.clear();

        for (String w : words) {
            for (int i = 0; i <= n; i++) {
                String pref = w.substring(0, i);
                prefixMap.computeIfAbsent(pref, k -> new ArrayList<>()).add(w);
            }
        }

        for (String w : words) {
            curr.add(w);
            backtrack(1);
            curr.remove(curr.size() - 1);
        }
        return res;
    }
}

var wordSquares = function(words) {
    const n = words[0].length;
    const prefixMap = new Map();
    for (const w of words) {
        for (let i = 0; i <= n; i++) {
            const pref = w.slice(0, i);
            if (!prefixMap.has(pref)) prefixMap.set(pref, []);
            prefixMap.get(pref).push(w);
        }
    }

    const res = [];
    const curr = [];

    function backtrack(step) {
        if (step === n) {
            res.push([...curr]);
            return;
        }
        let prefix = "";
        for (let i = 0; i < step; i++) {
            prefix += curr[i][step];
        }
        const cands = prefixMap.get(prefix) || [];
        for (const cand of cands) {
            curr.push(cand);
            backtrack(step + 1);
            curr.pop();
        }
    }

    for (const w of words) {
        curr.push(w);
        backtrack(1);
        curr.pop();
    }
    return res;
};

