#include <vector>

class Solution {
public:
    std::vector<int> xorQueries(std::vector<int>& arr, std::vector<std::vector<int>>& queries) {
        int n = arr.size();
        std::vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ arr[i];
        std::vector<int> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            res.push_back(pref[q[1] + 1] ^ pref[q[0]]);
        }
        return res;
    }
};

