        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] ^ arr[i];
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            res[i] = pref[queries[i][1] + 1] ^ pref[queries[i][0]];
        }
        return res;
    }
}

